import { createRoot } from 'react-dom/client';
import './index.css';
import * as React from 'react';
import { SampleBase } from './sample-base';
import { AccumulationChartComponent, AccumulationSeriesCollectionDirective, AccumulationSeriesDirective, AccumulationLegend, PieSeries, AccumulationDataLabel, AccumulationTooltip, AccumulationSelection, Inject, Selection, AccumulationAnnotationsDirective, AccumulationAnnotationDirective, ChartAnnotation, AccumulationAnnotation } from '@syncfusion/ej2-react-charts';
import { Browser } from '@syncfusion/ej2-base';
export let data1 = [
    { 'x': 'China', y: 35, text: '35%' },
    { 'x': 'India', y: 30, text: '30%' },
    { 'x': 'USA', y: 10.7, text: '10.7%' },
    { 'x': 'Indonesia', y: 7, text: '7%' },
    { 'x': 'Brazil', y: 5.3, text: '5.3%' },
    { 'x': 'Others', y: 12, text: '12%' },
];
let content = Browser.isDevice ? " " : "<div style='font-Weight:600;font-size:14px'>Internet Users <br> by Country<br>2025</div>";
const SAMPLE_CSS = `
    .control-fluid {
        padding: 0px !important;
    }
        .pie-chart2 {
            align :center
        }`;
export class Doughnut extends SampleBase {
    pie;
    render() {
        return (<div className='control-pane'>
      <style>{SAMPLE_CSS}</style>
      <div className='control-section'>
          <AccumulationChartComponent id='pie-chart2' load={this.load.bind(this)} legendSettings={{ visible: true, toggleVisibility: false, position: 'Bottom', textWrap: 'Wrap' }} enableBorderOnMouseMove={false} selectionMode='Point' tooltip={{ enable: true, format: '<b>${point.x}</b><br>Percentage: <b>${point.y}%</b>', header: "", enableHighlight: true }}>
              <Inject services={[AccumulationLegend, PieSeries, AccumulationDataLabel, AccumulationTooltip, AccumulationSelection, Selection, ChartAnnotation, AccumulationAnnotation]}/>
              <AccumulationSeriesCollectionDirective>
              <AccumulationSeriesDirective dataSource={data1} xName='x' yName='y' innerRadius='50%' borderRadius={3} border={{ width: 1, color: '#ffffff' }} dataLabel={{ visible: false }}/>
              </AccumulationSeriesCollectionDirective>
              <AccumulationAnnotationsDirective>
                  <AccumulationAnnotationDirective content={content} region="Series" x="50%" y="50%"/>
              </AccumulationAnnotationsDirective>
          </AccumulationChartComponent>
      </div>
  </div>);
    }
    load(args) {
        let selectedTheme = location.hash.split('/')[1];
        selectedTheme = selectedTheme ? selectedTheme : 'Fluent2';
        args.accumulation.theme = (selectedTheme.charAt(0).toUpperCase() + selectedTheme.slice(1)).replace(/-dark/i, "Dark").
            replace(/light/i, "Light").replace(/contrast/i, 'Contrast').replace(/-highContrast/i, 'HighContrast');
    }
    ;
}

const root = createRoot(document.getElementById('sample'));
root.render(<Doughnut />);

